PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS crane_models(id TEXT PRIMARY KEY, manufacturer TEXT NOT NULL, model TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chart_documents(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES crane_models(id), source_sha256 TEXT NOT NULL UNIQUE, source_commit TEXT NOT NULL, version TEXT NOT NULL, source_json TEXT NOT NULL CHECK(json_valid(source_json)), document_class TEXT NOT NULL, approval_status TEXT NOT NULL DEFAULT 'UNAPPROVED' CHECK(approval_status='UNAPPROVED'));
CREATE TABLE IF NOT EXISTS load_chart_tables(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES chart_documents(id), pdf_page INTEGER NOT NULL, metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)), approval_status TEXT NOT NULL DEFAULT 'UNAPPROVED' CHECK(approval_status='UNAPPROVED'), UNIQUE(id,document_id));
CREATE TABLE IF NOT EXISTS crane_configurations(id TEXT PRIMARY KEY, table_id TEXT NOT NULL REFERENCES load_chart_tables(id), document_id TEXT NOT NULL, conditions_json TEXT NOT NULL CHECK(json_valid(conditions_json)), resolution_status TEXT NOT NULL DEFAULT 'UNRESOLVED' CHECK(resolution_status='UNRESOLVED'), UNIQUE(table_id,id), FOREIGN KEY(table_id,document_id) REFERENCES load_chart_tables(id,document_id));
CREATE TABLE IF NOT EXISTS load_chart_entries(id TEXT PRIMARY KEY, table_id TEXT NOT NULL, document_id TEXT NOT NULL, configuration_id TEXT NOT NULL, pdf_page INTEGER NOT NULL, data_row INTEGER NOT NULL, data_column INTEGER NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), priority_json TEXT NOT NULL CHECK(json_valid(priority_json)), status TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK(status IN ('UNVERIFIED','VERIFIED','REJECTED','NEEDS_REVIEW')), corrected_json TEXT CHECK(corrected_json IS NULL OR json_valid(corrected_json)), revision INTEGER NOT NULL DEFAULT 0, UNIQUE(table_id,data_row,data_column), FOREIGN KEY(table_id,document_id) REFERENCES load_chart_tables(id,document_id), FOREIGN KEY(table_id,configuration_id) REFERENCES crane_configurations(table_id,id));
CREATE TABLE IF NOT EXISTS load_chart_reviews(id INTEGER PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES load_chart_entries(id), from_status TEXT NOT NULL, to_status TEXT NOT NULL, before_json TEXT, after_json TEXT, reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL, reason TEXT NOT NULL, revision INTEGER NOT NULL, UNIQUE(entry_id,revision));
CREATE TABLE IF NOT EXISTS load_chart_notes(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES chart_documents(id), pdf_page INTEGER NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TRIGGER IF NOT EXISTS immutable_extraction BEFORE UPDATE ON load_chart_entries WHEN NEW.raw_json!=OLD.raw_json OR NEW.id!=OLD.id OR NEW.table_id!=OLD.table_id OR NEW.configuration_id!=OLD.configuration_id OR NEW.document_id!=OLD.document_id OR NEW.pdf_page!=OLD.pdf_page OR NEW.data_row!=OLD.data_row OR NEW.data_column!=OLD.data_column OR NEW.priority_json!=OLD.priority_json BEGIN SELECT RAISE(ABORT,'immutable extraction'); END;
CREATE TRIGGER IF NOT EXISTS no_entry_delete BEFORE DELETE ON load_chart_entries BEGIN SELECT RAISE(ABORT,'immutable extraction'); END;
CREATE TRIGGER IF NOT EXISTS no_history_update BEFORE UPDATE ON load_chart_reviews BEGIN SELECT RAISE(ABORT,'append-only review history'); END;
CREATE TRIGGER IF NOT EXISTS no_history_delete BEFORE DELETE ON load_chart_reviews BEGIN SELECT RAISE(ABORT,'append-only review history'); END;
CREATE TRIGGER IF NOT EXISTS audited_entry_update BEFORE UPDATE OF status,corrected_json,revision ON load_chart_entries WHEN NEW.revision!=OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM load_chart_reviews r WHERE r.entry_id=OLD.id AND r.revision=NEW.revision AND r.from_status=OLD.status AND r.to_status=NEW.status AND r.before_json IS OLD.corrected_json AND r.after_json IS NEW.corrected_json) BEGIN SELECT RAISE(ABORT,'review history required before entry update'); END;
CREATE TRIGGER IF NOT EXISTS traceable_entry_insert BEFORE INSERT ON load_chart_entries WHEN NEW.pdf_page!=(SELECT pdf_page FROM load_chart_tables WHERE id=NEW.table_id) OR NEW.pdf_page!=json_extract(NEW.raw_json,'$.pdf_page') OR NEW.data_row!=json_extract(NEW.raw_json,'$.data_row') OR NEW.data_column!=json_extract(NEW.raw_json,'$.data_column') BEGIN SELECT RAISE(ABORT,'source location mismatch'); END;
